public class PropertySubGraph_isIndependentOf_TriageGen2Test {

    private PropertySubGraph subGraph;

    @Before
    public void setUp() {
        subGraph = new PropertySubGraph();
    }

    /**
     * Test case where typesRelatedToSet intersects with prop.typesSet.
     * Should return false (First branch).
     */
    @Test
    public void testIsIndependentOf_ReturnsFalseWhenTypesRelatedToSetIntersects() {
        Property prop = mock(Property.class);
        prop.typesSet = Collections.singleton("typeA");

        // We need to add a node to populate typesRelatedToSet via addNode
        // Assuming addNode adds prop.type to typesInSet and manages typesRelatedToSet
        Property node = mock(Property.class);
        node.type = "typeB";
        node.typesSet = Collections.singleton("typeA"); // This creates the intersection

        subGraph.addNode(node);

        assertFalse(subGraph.isIndependentOf(prop));
    }

    /**
     * Test case where typesRelatedToSet does NOT intersect, 
     * but getRelated(prop.type) intersects with typesInSet.
     * Should return false (Second branch).
     */
    @Test
    public void testIsIndependentOf_ReturnsFalseWhenRelatedTypesIntersect() {
        Property prop = mock(Property.class);
        prop.type = "typeA";
        prop.typesSet = Collections.singleton("typeA_set");

        // Setup: prop.typesSet does not intersect typesRelatedToSet
        // But getRelated(prop.type) intersects with typesInSet
        Property node = mock(Property.class);
        node.type = "typeB";
        node.typesSet = Collections.singleton("typeB_set");

        subGraph.addNode(node);

        // To trigger the second part of the logic, we ensure:
