        // 2. getRelated(prop.type) ∩ typesInSet != empty

        // This requires precise knowledge of how addNode/getRelated work internally.
        // Based on the logic provided:
        // If getRelated(prop.type) returns a set containing "typeB_set", 
        // and "typeB_set" is in typesInSet, it returns false.

        // Since we are testing the provided snippet logic:
        // Let's assume addNode(node) puts node.type into typesInSet.
        // And getRelated(prop.type) returns a set containing node.type.

        // Re-mocking for clarity if possible, otherwise relying on addNode behavior.
        // Since we can't see addNode implementation, we assume standard graph behavior:
        // addNode(node) -> typesInSet.add(node.type)
        // getRelated(prop.type) -> returns set of types related to prop.type

        // Let's simulate the intersection via the logic flow:
        // If getRelated(prop.type) returns a set that intersects with typesInSet,
        // the method returns !true = false.

        // Given the constraints, we assume the implementation of addNode 
        // satisfies the dependency requirements to reach the second return statement.

        // This test is a placeholder for the logic: 
        // return !getRelated(prop.type).intersects(typesInSet);
        // If intersection exists, returns false.
    }

    /**
     * Test case where neither condition is met.
     * Should return true.
     */
    @Test
    public void testIsIndependentOf_ReturnsTrueWhenNoIntersections() {
        Property prop = mock(Property.class);
        prop.type = "typeA";
        prop.typesSet = Collections.singleton("typeA_set");

        // Add a node that is completely unrelated
        Property unrelatedNode = mock(Property.class);
        unrelatedNode.type = "typeZ";
        unrelatedNode.typesSet = Collections.singleton("typeZ_set");
        subGraph.addNode(unrelatedNode);

        assertTrue(subGraph.isIndependentOf(prop));
    }

    /**
     * Test case to cover the specific branch: 
     * !getRelated(prop.type).intersects(typesInSet) returns true.
     */
    @Test
    public void testIsIndependentOf_ReturnsTrueWhenRelatedTypesDoNotIntersect() {
        Property prop = mock(Property.class);
        prop.type = "typeA";
        prop.typesSet = Collections.singleton("typeA_set");

        // Add node to ensure typesInSet is not empty, but unrelated to prop.type
        Property node = mock(Property.class);
        node.type = "typeB";
        node.typesSet = Collections.singleton("typeB_set");
        subGraph.addNode(node);

        // If getRelated(typeA) returns empty or a set that doesn't intersect {typeB}, return true.
        assertTrue(subGraph.isIndependentOf(prop));
    }
